		<div class="elementor-element elementor-element-039d8b2 e-flex e-con-boxed e-con e-parent" data-id="039d8b2" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
