INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (10554, 'Câu chuyện bài học về May Mắn &#8211; Cảm Xúc Cuộc Sống', 'bai-hoc-ve-may-man', '<p>Năm 2003, <a href="https://en.wikipedia.org/wiki/Richard_Wiseman" target="_blank" rel="noreferrer noopener">Tiến sĩ Richard Wiseman</a> xuất bản cuốn Yếu tố may mắn, khám phá lý do tại sao một số người luôn gặp may mắn trong khi những người khác phải vật lộn với vận rủi cả đời.</p>
<p>Ông tập hợp những người tham gia vào một số thí nghiệm đơn giản: Tiến sĩ Wiseman lấy ra các quảng cáo yêu cầu người tham gia nghiên cứu về may mắn &#8211; cụ thể là các quảng cáo yêu cầu những người tự coi mình là rất may mắn hoặc rất xui xẻo.</p>
<p>Trong một thí nghiệm, mỗi người tham gia được đưa cho một tờ báo và được yêu cầu đếm số lượng ảnh bên trong tờ báo đó. Nhóm kém may mắn mất trung bình 2 phút để hoàn thành bài tập, trong khi nhóm may mắn chỉ mất trung bình vài giây.</p>
<p><strong>Chuyện gì đã xảy ra thế?</strong></p>
<p>Chà, ở trang 2 của tờ báo, có một dòng chữ in đậm rất lớn,</p>
<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>&#8220;Đừng đếm nữa, có 43 bức ảnh trong tờ báo này.&#8221;</p>
</blockquote>
<p>Ở nửa chặng đường, có một thông báo khác có nội dung: &#8220;Dừng đếm, nói với người thử nghiệm rằng bạn đã nhìn thấy điều này và giành được 250 đô la.&#8221;</p>
<p>Những người may mắn tự nhận mình đã nhìn thấy dòng chữ, dừng lại và phản ứng tương ứng để kết thúc đồng hồ (hoặc thu tiền). Mặt khác, những người tự nhận mình là người không may mắn đã bỏ lỡ nó (hoặc không tin tưởng vào nó) và mất nhiều thời gian hơn để đếm.</p>
<p>Phát hiện này đã trở thành một chủ đề nhất quán xuyên suốt toàn bộ nghiên cứu:</p>
<p><strong>Người may mắn bắt gặp những cơ hội “ngẫu nhiên”, còn người kém may mắn dường như bỏ lỡ chúng. Cả hai nhóm đều có quyền tiếp cận những cơ hội này như nhau, nhưng nhóm may mắn nhìn thấy những gì mà nhóm không may mắn có xu hướng bỏ lỡ.</strong></p>
<p>Có một khái niệm mà tôi thường gọi là “diện tích bề mặt may mắn” trong bài viết của mình. Ý tưởng là mỗi chúng ta đều có một bề mặt mà những sự kiện may mắn có thể xảy ra.</p>
<p>Có một số yếu tố cơ bản nằm ngoài tầm kiểm soát của chúng ta:</p>
<ul class="wp-block-list">
<li>Nơi bạn sinh ra</li>
<li>Bạn sinh ra cho ai</li>
<li>&#8220;Thiên ý&#8221;</li>
</ul>
<p>Ngoài những yếu tố này, kích thước của diện tích bề mặt may mắn nằm trong tầm kiểm soát của chúng ta.</p>
<p>Trong nghiên cứu của Tiến sĩ Wiseman, những người may mắn dường như hiểu được điều này:</p>
<ul class="wp-block-list">
<li>Họ lưu ý rằng họ thường đi các tuyến đường khác nhau đến và đi từ nơi làm việc để gặp gỡ những người mới và nhìn thấy những điều mới.</li>
<li>Họ nói về những chiến lược độc đáo để nói chuyện với các nhóm người khác nhau trong các bữa tiệc.</li>
<li>Họ đã phục hồi sau những cuộc gặp gỡ có vẻ tiêu cực và duy trì quan điểm tích cực về tương lai.</li>
</ul>
<p>Những người may mắn nhất đã tạo ra được một bề mặt may mắn khổng lồ.</p>
<p>Mở rộng của bạn theo 2 cách:</p>
<ol class="wp-block-list">
<li>Loại bỏ điều không may mắn: Điều không may mắn bao gồm tất cả những hành động, hành vi và con người làm thu hẹp bề mặt may mắn của bạn. Sự bi quan và sự “mù quáng” là hai nguyên nhân phổ biến dẫn đến sự kém may mắn. Những người khuyên bạn nên thực tế cũng là một nguồn phổ biến khác.</li>
<li>Thêm sự may mắn: Sự may mắn bao gồm tất cả các hành động, hành vi và con người giúp mở rộng diện tích bề mặt may mắn của bạn. Ra ngoài và gặp gỡ những người mới, chia sẻ suy nghĩ và ý tưởng của bạn một cách công khai, đồng thời gửi nhiều email và tin nhắn trực tiếp lạnh lùng hơn đều là những nguồn mang lại may mắn phổ biến. Những người khuyến khích bạn nghĩ lớn hơn cũng là một nguồn phổ biến khác.</li>
</ol>
', 'Năm 2003, Tiến sĩ Richard Wiseman xuất bản cuốn Yếu tố may mắn, khám phá lý do tại sao một số người luôn gặp may mắn trong khi những người khác phải vật lộn với vận rủi cả đời. Ông tập hợp những người tham gia vào một số thí nghiệm đơn giản: Tiến sĩ [&hellip;]', 10556, 'post', '2023-08-22 13:48:42', '2023-08-22 13:48:43');

