INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (10537, 'Mẹo quản lý thời gian &#8211; Time Management', 'meo-quan-ly-thoi-gian', '		<div data-elementor-type="wp-post" data-elementor-id="10537" class="elementor elementor-10537" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-f3e9896 e-con-full e-flex e-con e-parent" data-id="f3e9896" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-846e0cc e-con-full e-flex e-con e-parent" data-id="846e0cc" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-de12cc1 e-flex e-con-boxed e-con e-parent" data-id="de12cc1" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-5b8e63c elementor-widget elementor-widget-heading" data-id="5b8e63c" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<div class="elementor-heading-title elementor-size-default">Cơ bản</div>				</div>
				</div>
				<div class="elementor-element elementor-element-c9d39c9 elementor-icon-list--layout-traditional elementor-list-item-link-full_width elementor-widget elementor-widget-icon-list" data-id="c9d39c9" data-element_type="widget" data-widget_type="icon-list.default">
				<div class="elementor-widget-container">
							<ul class="elementor-icon-list-items">
							<li class="elementor-icon-list-item">
											<a href="https://huynhhieutravel.com/chan-dung-khach-hang/">

												<span class="elementor-icon-list-icon">
							<i aria-hidden="true" class="fas fa-check"></i>						</span>
										<span class="elementor-icon-list-text">Cách tạo Chân dung Người dùng cho doanh nghiệp</span>
											</a>
									</li>
								<li class="elementor-icon-list-item">
											<a href="https://huynhhieutravel.com/huong-dan-viet-case-study/">

												<span class="elementor-icon-list-icon">
							<i aria-hidden="true" class="fas fa-check"></i>						</span>
										<span class="elementor-icon-list-text">Hướng dẫn viết Case Study</span>
											</a>
